mapper.select:
select * from ( select
(NVL(day_plan_qty, 0) + NVL(night_plan_qty, 0)) as daily_total_qty, floor(fq.DAY_FINISH_QTY) as DAY_FINISH_QTY, (case when a.day_plan_qty=0 then null when a.day_plan_qty!=0 then (floor(fq.DAY_FINISH_QTY)/a.day_plan_qty) end) as day_finish_rate, floor(fq.NIGHT_FINISH_QTY) as NIGHT_FINISH_QTY, (case when a.night_plan_qty=0 then null when a.night_plan_qty!=0 then (floor(fq.NIGHT_FINISH_QTY)/a.night_plan_qty) end) as night_finish_rate, b.MONTH_PLAN_QTY as month_plan, ceil(b.MONTH_REMAIN_QTY) as month_plan_os, log.change_machine, log.change_day_plan, log.change_night_plan from t_nc_schedule_result a LEFT JOIN ( SELECT MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY FROM T_NC_MONTH_PLAN_SURPLUS WHERE del_flag='0' and YEAR=#{year,jdbcType=VARCHAR} and MONTH=#{month,jdbcType=VARCHAR} ) b on a.lining_code=b.MATERIAL_CODE LEFT JOIN T_NC_DAY_FINISH_QTY fq on a.order_no = fq.order_no and fq.del_flag = '0' LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(decode(BEFORE_MACHINE_ID, AFTER_MACHINE_ID,0,1)) change_machine, max(decode(BEFORE_DAY_PLAN, AFTER_DAY_PLAN,0,1)) change_day_plan, max(decode(BEFORE_NIGHT_PLAN, AFTER_NIGHT_PLAN,0,1)) change_night_plan FROM T_NC_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag='0' and a.schedule_date = #{scheduleDate} and a.SUPPLY_TIME >= #{supplyStartTime,jdbcType=DECIMAL} and a.SUPPLY_TIME <= #{supplyEndTime,jdbcType=DECIMAL} and INSTR(a.lining_code, #{liningCode,jdbcType=VARCHAR}) > 0 and INSTR(a.glue_code, #{glueCode,jdbcType=VARCHAR}) > 0 and a.IS_RELEASE = #{isRelease} and instr(','||a.machine_id||',', ','||#{machineId}||',')>0 and a.id in #{scheduleId} order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/, to_number(substr(a.glue_seq,0,instr(a.glue_seq,'.')-1)), to_number(substr(a.glue_seq,instr(a.glue_seq,'.')+1)) asc ) t
order by ${orderStr}


where del_flag='0'
and id != #{id,jdbcType=DECIMAL}
and schedule_date = #{scheduleDate,jdbcType=DATE}
and machine_id = #{machineId,jdbcType=VARCHAR}
and lining_code = #{liningCode,jdbcType=VARCHAR}

mapper.update:
update t_nc_schedule_result
schedule_date = #{scheduleDate}, cx_batch_no = #{cxBatchNo}, batch_no = #{batchNo}, order_no = #{orderNo}, lining_code = #{liningCode}, glue_code = #{glueCode}, whole_glue_code = #{wholeGlueCode}, glue_seq = #{glueSeq}, mouth_plate_code = #{mouthPlateCode}, unit_consume = #{unitConsume}, machine_id = #{machineId}, stock_qty = #{stockQty}, supply_time = #{supplyTime}, day_plan_qty = #{dayPlanQty,jdbcType=DECIMAL}, day_finish_qty = #{dayFinishQty}, day_produce_order = #{dayProduceOrder,jdbcType=DOUBLE}, day_finish_rate = #{dayFinishRate}, day_sys_analysis = #{daySysAnalysis}, day_hand_analysis = #{dayHandAnalysis,jdbcType=VARCHAR}, night_plan_qty = #{nightPlanQty,jdbcType=DECIMAL}, night_finish_qty = #{nightFinishQty}, night_produce_order = #{nightProduceOrder,jdbcType=DOUBLE}, night_finish_rate = #{nightFinishRate}, night_sys_analysis = #{nightSysAnalysis}, night_hand_analysis = #{nightHandAnalysis,jdbcType=VARCHAR}, pre_plan_qty = #{prePlanQty}, cx_class1_plan = #{cxClass1Plan}, cx_class2_plan = #{cxClass2Plan}, cx_class3_plan = #{cxClass3Plan}, cx_class4_plan = #{cxClass4Plan}, cx_class5_plan = #{cxClass5Plan}, is_release = #{isRelease}, remark = #{remark}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}

update t_nc_schedule_result set IS_RELEASE= #{status}
, PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = sysdate
where id in

    #{id}

